-- ================================================
-- MIGRATION 049: SEED FULL PRODUCT CATALOG FROM SALES REPORT
-- Populates full catalog of 284 products across 14 categories
-- ================================================

-- 1. Insert Categories

-- 2. Insert Products

-- 3. Sync branch_products for all active branches (stock set to 999 for instant POS availability)
SELECT b.id, p.id, 999, 5, true
FROM branches b
CROSS JOIN products p
ON CONFLICT (branch_id, product_id) DO NOTHING;

-- 4. Sync warehouse_stock for all warehouses if warehouse table exists
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'warehouse') THEN
    SELECT w.id, p.id, 999, 5
    FROM warehouse w
    CROSS JOIN products p
    ON CONFLICT (warehouse_id, product_id) DO NOTHING;
  END IF;
END $$;
